$_MODULE['<{ntbackupandrestore}prestashop>faq_51452b6d1f8511cf289eb01753eda3bb'] = 'L\'automazione è stata fatta da 2N quotidiana';
$_MODULE['<{ntbackupandrestore}prestashop>faq_42027eaa203032a09ccc5048897c677c'] = 'L\'automazione da 2N sembra non funzionare più, cosa posso fare?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_ffebb8fcef9bdccc3aeac353e6d78be7'] = 'Per favore prova a salvarlo di nuovo';
$_MODULE['<{ntbackupandrestore}prestashop>faq_41906c69303e903c986fde8f7cb34665'] = 'Il backup terminato con un errore che indica che non vi è abbastanza spazio per il backup,ma io sono dove è. Perchè ho questo errore?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_8bdbb9087cc2864414759889f6d22307'] = 'Questo errore può essere causato da un limite del server. Alcuni server (32 bits)non consentirà al backup di essere superiore a 2 GB. In questo caso, tu puoi usare questa opzione avanzata per limitare la misura del backup. Il tuo backup sarà tagliato in piccole parti che saranno accettate dal server.Per esempio,tu puoi scegliere 1500 come misura limiteper il tuo backup file.Presta attenzione che tutte le parti sono obbligatorie se tu vuoi riprisstinare il tuo negozio.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_afde1c7273735610102d9f166386b91e'] = 'Dove possocercare il mio file di backup sul server?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_c99296863a8cfebedbf941a80b149eb3'] = 'È possibile trovare il backup nella directory modules/ntbackupandrestore/backup/ per impostazione predefinita o nella directory configurata nella configurazione avanzata.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_6162f1ad35f8d68d2ad18e65d6af12ca'] = 'Dove posso cercare l\'archivio nel mio backup?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_259f134b1c3cb0f4211d27812fb4f339'] = 'Quando tu crei un backup completo, il tuo archivioè salvato con altri file di backup.Se tu vuoi controllare,  annulla il tuo file di backup sul computer, tu puoi trovare il dump.sql nei moduli della directory /ntbackupandrestore/backup/';
$_MODULE['<{ntbackupandrestore}prestashop>faq_d50856eaf5567a344aafac6b6629a581'] = 'Come posso verificare se il mio backup è valido?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_d2a25247fc786e9f6a27212ee9aed0b8'] = 'Il modo migliore per capire se il backup è valido, è provare a ripristinare qualche altra cosa. Per esempio, su un nuovo dominio e archivio o sul computer con  Wamp, Mamp, Easyphp o altri server locali e softwares.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_b26bae87fdb843d75a120d12fe51ffa6'] = 'Come posso riprostinare il mio backup?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_84d3c56657e5438d10f92c3d36c5cf8b'] = 'Per ripristinare il backup c\'è bisogno di:';
$_MODULE['<{ntbackupandrestore}prestashop>faq_261aa829c8bd1bd4216bf09dc76f7326'] = 'Scegli dove bloccherai il ripristino. O un nuovo luogo(nuovo dominio e archivio)per copiare/muovere o aa fissare il negozio attuale per le sue sostituzioni.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0c02578d80e75b15e3c2fafda964bfe4'] = 'Metti il tuo backup e ripristino del copione ad un luogo scelto';
$_MODULE['<{ntbackupandrestore}prestashop>faq_967e66ec729f29106f185bf0e5c9c267'] = 'Accedi al ripristino del copione, usando il tuo web browser';
$_MODULE['<{ntbackupandrestore}prestashop>faq_96c158c212b69d93f4bf51a208b7c6b0'] = 'Riempire le credenziali di accesso dell\'archivio dove l\'archivio è stato ripristinato.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_3438a63edfc1456e8bff9b8a75f0f8c2'] = 'Opzionale: se ne hai bisogno, configura le opzioni avanzate';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0b20e24f98a55bf66d6fe76363284591'] = 'Lancia la restaurazione.Fai attenzione che il file dal tuo backup sarà sovrascritto su un potenziale esistente file e archiviosaranno sostituita dall\'archivio del tuo backup.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_6510898b2f7a8fa6fe8aeafb9ea5ca4d'] = 'Per ripristinare il negozio, devo prima installare vuoto il Prestashop?.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_2f8b950c8cb11678dd68bd1050f15034'] = 'Tu non hai bisogno di installare vuoto il Prestashop per ripristinare.hai solo bisogno del backup file e del ripristino del copione.';
