$_MODULE['<{ntbackupandrestore}prestashop>faq_d22b5ed685107fdea35dd423a0adc8e4'] = 'Il backup completo conterrà una copia esatta del tuo sito web, il che significa che tutti i tuoi file e dati, ad eccezione di file e dati di basso interesse (cache, registri ...) che non vengono salvati perché le loro dimensioni sono grandi e sono di scarsa utilità durante un ripristino. Puoi comunque dire al modulo di salvarli nelle opzioni avanzate.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_c7b627aacbd45fc86611dc65afcd11fc'] = 'Non ho abbastanza spazio sul mio server per il backup, posso inviarlo direttamente a uno dei miei account remoti (%1$s, %2$s...)?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_0ec06b6f186a84a008827f4ee4efdff2'] = 'Prima di poter essere inviato a un account remoto, è necessario creare il backup sul server. È necessario disporre almeno di spazio per un backup. È possibile scegliere nella configurazione avanzata l\'opzione che consente la cancellazione automatica del backup locale se viene inviato a un account remoto. Se non si dispone di spazio sufficiente per un backup, è possibile abilitare l\'invio diretto (senza backup locale) al server remoto (ad eccezione di FTP e Box), ma in questo caso il backup non verrà compresso.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_50fe9d94822e8a6d1ed52600d8c071cc'] = 'Come aggiornare il modulo?';
$_MODULE['<{ntbackupandrestore}prestashop>faq_c45a02babc859c783cc1a5b21b62cdfd'] = 'È necessario scaricare l\'ultima versione del modulo da dove è stato acquistato.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_cf832f19d14486b25d11aaf8e9cc016d'] = 'Quindi nel backoffice del tuo negozio, in Modules > Modules Manager, fai clic sul pulsante Installa modulo e scegli il file zip del modulo.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_a9f902c1ce6abfbf5cd3573d49973d87'] = 'Prestashop rileverà la tua versione corrente e aggiornerà automaticamente il tuo modulo.';
$_MODULE['<{ntbackupandrestore}prestashop>faq_3384251ff34a299aae3717020c8e0bfd'] = 'Non è necessario disinstallare prima il modulo.';
